cat > src/billing/payment-terms.test.ts <<'EOF'
import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { defaultConfig, loadConfig } from '../config.ts';
import { createTestApp, ON_ADDRESS } from '../lib/testing.ts';
import { buildInvoice } from './invoice.ts';

const DAY_MS = 24 * 60 * 60 * 1000;

function dueAfter(paymentTermsDays?: number): { issuedAt: string; dueAt: string } {
  const app = createTestApp();
  const config = paymentTermsDays === undefined ? app.ctx.config : { ...app.ctx.config, paymentTermsDays };
  const invoice = buildInvoice(
    { ...app.ctx, config },
    {
      orderId: 'ord_0001',
      userId: 'usr_0001',
      address: ON_ADDRESS,
      items: [{ productId: 'prd_0001', description: 'Thing', quantity: 1, unitPrice: 1000, taxClass: 'standard' }],
    },
  );
  return invoice;
}

const days = (inv: { issuedAt: string; dueAt: string }) =>
  (new Date(inv.dueAt).getTime() - new Date(inv.issuedAt).getTime()) / DAY_MS;

describe('paymentTermsDays config', () => {
  it('defaults to 30', () => {
    assert.equal((defaultConfig as unknown as Record<string, unknown>).paymentTermsDays, 30);
    assert.equal((loadConfig({}) as unknown as Record<string, unknown>).paymentTermsDays, 30);
  });

  it('is overridden by PAYMENT_TERMS_DAYS', () => {
    assert.equal((loadConfig({ PAYMENT_TERMS_DAYS: '60' }) as unknown as Record<string, unknown>).paymentTermsDays, 60);
  });

  it('keeps the default when PAYMENT_TERMS_DAYS is empty', () => {
    assert.equal((loadConfig({ PAYMENT_TERMS_DAYS: '' }) as unknown as Record<string, unknown>).paymentTermsDays, 30);
  });

  it('rejects a non-numeric PAYMENT_TERMS_DAYS', () => {
    assert.throws(() => loadConfig({ PAYMENT_TERMS_DAYS: 'soon' }), /invalid integer/);
  });
});

describe('invoice due date', () => {
  it('is 30 days after issue by default', () => {
    assert.equal(days(dueAfter()), 30);
  });

  it('uses the configured paymentTermsDays', () => {
    assert.equal(days(dueAfter(45)), 45);
    assert.equal(days(dueAfter(7)), 7);
  });

  it('is due on the issue date when terms are 0', () => {
    const inv = dueAfter(0);
    assert.equal(inv.dueAt, inv.issuedAt);
  });

  it('uses the terms from an app built with PAYMENT_TERMS_DAYS', () => {
    const config = loadConfig({ PASSWORD_COST: '16', PAYMENT_TERMS_DAYS: '14' });
    const app = createTestApp();
    const invoice = buildInvoice(
      { ...app.ctx, config },
      {
        orderId: 'ord_0001',
        userId: 'usr_0001',
        address: ON_ADDRESS,
        items: [{ productId: 'prd_0001', description: 'Thing', quantity: 1, unitPrice: 1000, taxClass: 'standard' }],
      },
    );
    assert.equal(days(invoice), 14);
  });
});
EOF
