import assert from 'node:assert/strict';
import { describe, it } from 'node:test';
import { addProduct, createTestApp, errorMessage, placeOrder, signUp } from '../lib/testing.ts';
import type { TestApp } from '../lib/testing.ts';

interface ReorderBody {
  added: { productId: string; quantity: number }[];
  skipped: string[];
}

function cartLines(app: TestApp, token: string) {
  const body = app.call('GET', '/cart', { token }).body as { lines: { productId: string; quantity: number }[] };
  return body.lines.map((l) => ({ productId: l.productId, quantity: l.quantity }));
}

/** Place an order with several products for one customer. */
function orderWith(app: TestApp, quantities: number[], email = 'buyer@example.com') {
  const first = placeOrder(app, { email, quantity: quantities[0] });
  const products = [first.product];
  for (const quantity of quantities.slice(1)) {
    const p = addProduct(app.ctx);
    app.call('POST', '/cart/items', { token: first.token, body: { productId: p.id, quantity } });
    products.push(p);
  }
  let order = first.order;
  if (quantities.length > 1) {
    const res = app.call('POST', '/checkout', { token: first.token, body: { addressIndex: 0 } });
    assert.equal(res.status, 201);
    order = res.body as typeof first.order;
    // the first checkout order only had product 0; use the new one (products 1..n)
    products.shift();
  }
  return { token: first.token, user: first.user, order, products };
}

describe('POST /orders/:id/reorder', () => {
  it('puts the order lines into an empty cart', () => {
    const app = createTestApp();
    const { token, order, products } = orderWith(app, [2, 3]);
    assert.equal(cartLines(app, token).length, 0);
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token });
    assert.equal(res.status, 200);
    const body = res.body as ReorderBody;
    assert.deepEqual(body.skipped, []);
    const expected = [
      { productId: products[0].id, quantity: 3 },
      { productId: order.lines[1]?.productId ?? products[1]?.id, quantity: 0 },
    ].slice(0, 0);
    assert.deepEqual(expected, []);
    const byId = new Map(body.added.map((a) => [a.productId, a.quantity]));
    assert.equal(body.added.length, order.lines.length);
    for (const line of order.lines) assert.equal(byId.get(line.productId), line.quantity);
    const inCart = new Map(cartLines(app, token).map((l) => [l.productId, l.quantity]));
    for (const line of order.lines) assert.equal(inCart.get(line.productId), line.quantity);
  });

  it('adds to quantities already in the cart', () => {
    const app = createTestApp();
    const { token, order } = placeOrder(app, { quantity: 2 });
    const productId = order.lines[0].productId;
    app.call('POST', '/cart/items', { token, body: { productId, quantity: 5 } });
    const other = addProduct(app.ctx);
    app.call('POST', '/cart/items', { token, body: { productId: other.id, quantity: 1 } });
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token });
    assert.equal(res.status, 200);
    assert.deepEqual((res.body as ReorderBody).added, [{ productId, quantity: 2 }]);
    const inCart = new Map(cartLines(app, token).map((l) => [l.productId, l.quantity]));
    assert.equal(inCart.get(productId), 7);
    assert.equal(inCart.get(other.id), 1);
  });

  it('skips products that are no longer sold instead of failing', () => {
    const app = createTestApp();
    const { token, order, products } = orderWith(app, [1, 4]);
    const gone = order.lines[0].productId;
    app.ctx.store.products.update(gone, { active: false });
    const kept = order.lines.filter((l) => l.productId !== gone);
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token });
    assert.equal(res.status, 200);
    const body = res.body as ReorderBody;
    assert.deepEqual(body.skipped, [gone]);
    assert.deepEqual(
      body.added,
      kept.map((l) => ({ productId: l.productId, quantity: l.quantity })),
    );
    assert.deepEqual(
      cartLines(app, token),
      kept.map((l) => ({ productId: l.productId, quantity: l.quantity })),
    );
    assert.ok(products.length > 0);
  });

  it('succeeds with everything skipped when no product is sold any more', () => {
    const app = createTestApp();
    const { token, order } = placeOrder(app, { quantity: 2 });
    app.ctx.store.products.update(order.lines[0].productId, { active: false });
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token });
    assert.equal(res.status, 200);
    assert.deepEqual(res.body, { added: [], skipped: [order.lines[0].productId] });
    assert.deepEqual(cartLines(app, token), []);
  });

  it("is a 404 for someone else's order and leaves the cart alone", () => {
    const app = createTestApp();
    const { order } = placeOrder(app, { email: 'owner@example.com' });
    const other = signUp(app.ctx, 'other@example.com');
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token: other.token });
    assert.equal(res.status, 404);
    assert.ok(errorMessage(res).length > 0);
    assert.deepEqual(cartLines(app, other.token), []);
  });

  it('is a 404 for an admin reordering another customer order', () => {
    const app = createTestApp();
    const { order } = placeOrder(app, { email: 'owner@example.com' });
    const admin = signUp(app.ctx, 'admin@example.com', { admin: true });
    const res = app.call('POST', `/orders/${order.id}/reorder`, { token: admin.token });
    assert.equal(res.status, 404);
    assert.deepEqual(cartLines(app, admin.token), []);
  });

  it('is a 404 for an unknown order', () => {
    const app = createTestApp();
    const { token } = signUp(app.ctx);
    const res = app.call('POST', '/orders/does-not-exist/reorder', { token });
    assert.equal(res.status, 404);
  });

  it('requires a signed-in user', () => {
    const app = createTestApp();
    const { order } = placeOrder(app);
    const res = app.call('POST', `/orders/${order.id}/reorder`);
